sed -i '87i\                Pousada Maré Alta,revenue,2027-04' ReportsTest.java &&
sed -i '104i\                Pousada Maré Alta,revenue,2027-05' ReportsTest.java &&
sed -i '116i\                Pousada Maré Alta,revenue,2027-06' ReportsTest.java &&
# new tests before final brace
sed -i '$d' ReportsTest.java && cat >> ReportsTest.java <<'EOF'

    @Test
    void tourismTaxChargesEachGuestForEachNightOfThePaidReservations() {
        Reservation family = service.create(new NewReservation(
                302, new Guest("Ana Souza", "ana@example.com", "123.456.789-00"),
                LocalDate.parse("2027-04-10"), LocalDate.parse("2027-04-13"), 2, RatePlan.STANDARD));
        service.confirm(family.id());

        String csv = new TourismTaxReport(store, new BigDecimal("4.50")).generate(YearMonth.of(2027, 4));

        // the unpaid and the cancelled reservations pay no tax
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-04
                reservation,room,check_in,check_out,guests,nights,tax
                1,201,2027-04-01,2027-04-03,1,2,9.00
                3,301,2027-04-02,2027-04-04,1,2,9.00
                6,302,2027-04-10,2027-04-13,2,3,27.00
                total,45.00
                """, csv);
    }

    @Test
    void ratePlansHaveOneLineEachEvenWithoutReservations() {
        String csv = new RatePlanReport(store).generate(YearMonth.of(2027, 4));

        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-04
                rate_plan,reservations,amount
                STANDARD,2,1939.60
                NON_REFUNDABLE,0,0.00
                total,2,1939.60
                """, csv);
    }
}
